def transform(grid):
    bg = grid[0][0]
    out = [row[:] for row in grid]
    for r, row in enumerate(grid):
        for c, v in enumerate(row):
            if v == 5:
                end = c
                while end + 1 < len(row) and row[end+1] == bg:
                    end += 1
                for k in range(c+1, end+1):
                    out[r][k] = 3
    return out
